"""Source-gated trail-to-street bicycle construction for LVMC 11.22.120(B)."""
from __future__ import annotations

import hashlib
import json
import math


def canonical_sha(value: dict) -> str:
    return hashlib.sha256(json.dumps(value, sort_keys=True, separators=(",", ":")).encode()).hexdigest()


def _point(value):
    if not isinstance(value, list) or len(value) != 3 or not all(isinstance(v, (int, float)) and math.isfinite(v) for v in value):
        raise ValueError("source point must have three finite coordinates")
    return value


def validate_site(site: dict) -> dict:
    """Require external designation, governed roadway, actual sign and connected route."""
    for key in ("map_name", "jurisdiction_source", "engineer_designation_source", "street_id", "bicycle_blueprint_id"):
        if not isinstance(site.get(key), str) or not site[key].strip():
            raise ValueError(f"missing original site field: {key}")
    if site.get("designation_street_id") != site["street_id"]:
        raise ValueError("designation does not bind governed street")
    if site.get("designation_prohibits_bicycle_roadway_use") is not True:
        raise ValueError("designation lacks bicycle roadway restriction")
    segments = site.get("route_segments")
    if not isinstance(segments, list) or len(segments) < 2:
        raise ValueError("trail and street route segments required")
    if segments[0].get("kind") != "nonmotorized_trail" or segments[1].get("kind") != "governed_street_roadway":
        raise ValueError("route must connect trail to governed street roadway")
    if segments[1].get("street_id") != site["street_id"]:
        raise ValueError("route street differs from designation")
    for segment in segments[:2]:
        start, end = _point(segment.get("start")), _point(segment.get("end"))
        if math.dist(start, end) < 1.0:
            raise ValueError("degenerate route segment")
    if math.dist(segments[0]["end"], segments[1]["start"]) > 0.5:
        raise ValueError("trail route does not connect to street")
    sign = site.get("sign")
    if not isinstance(sign, dict) or sign.get("street_id") != site["street_id"]:
        raise ValueError("sign does not govern designated street")
    for key in ("source_id", "wording", "facing_direction", "erection_source", "native_blueprint_id"):
        if not isinstance(sign.get(key), str) or not sign[key].strip():
            raise ValueError(f"missing original sign field: {key}")
    _point(sign.get("position"))
    if sign.get("posted") is not True or sign.get("prohibits_bicycle_roadway_use") is not True:
        raise ValueError("posted sign does not state bicycle roadway restriction")
    return {"site_sha256": canonical_sha(site), "street_id": site["street_id"], "sign_source_id": sign["source_id"]}


def spawn_bicycle(world, transform, site: dict):
    """Call Native spawn/readback only after site source validation."""
    validate_site(site)
    blueprint = world.get_blueprint_library().find(site["bicycle_blueprint_id"])
    bike = world.try_spawn_actor(blueprint, transform)
    if bike is None or not bike.is_alive or bike.type_id != site["bicycle_blueprint_id"]:
        raise ValueError("Native bicycle spawn/readback failed")
    return bike


def command_bicycle(bike, carla, site: dict, case: dict, elapsed_s: float) -> dict:
    validate_site(site)
    if not bike.is_alive or bike.type_id != site["bicycle_blueprint_id"]:
        raise ValueError("Native bicycle readback failed")
    if case.get("motion") not in ("enter_roadway", "remain_trail", "stop_before_roadway"):
        raise ValueError("unknown case motion")
    location = bike.get_location()
    if not all(math.isfinite(v) for v in (location.x, location.y, location.z)):
        raise ValueError('Native bicycle position readback unavailable')
    trail = site['route_segments'][0]
    junction_distance = math.dist([location.x, location.y], trail['end'][:2])
    on_trail = junction_distance > 1.0
    segment = trail if (on_trail or case['motion'] != 'enter_roadway') else site['route_segments'][1]
    start, end = segment["start"], segment["end"]
    dx, dy = end[0] - start[0], end[1] - start[1]
    length = math.hypot(dx, dy)
    if length < 1.0:
        raise ValueError("degenerate route segment")
    scale = case.get('engineering_speed_scale', 1.0)
    if not isinstance(scale, (int, float)) or not math.isfinite(scale) or not 0.25 <= scale <= 1.0:
        raise ValueError('unsafe engineering speed scale')
    speed = float(site.get("engineering_speed_mps", 3.0)) * scale
    if case['motion'] != 'enter_roadway' and junction_distance <= 1.0:
        speed = 0.0
    if not math.isfinite(speed) or not 0 <= speed <= 8:
        raise ValueError("unsafe engineering speed")
    command = carla.Vector3D(x=dx / length * speed, y=dy / length * speed, z=0.0)
    bike.set_target_velocity(command)
    actual = bike.get_velocity()
    if not all(math.isfinite(v) for v in (actual.x, actual.y, actual.z)):
        raise ValueError("Native velocity readback unavailable")
    return {"source_kind": "original_native_control_readback", "actor_id": str(bike.id), "site_sha256": canonical_sha(site), "elapsed_s": elapsed_s, "motion": case["motion"], "junction_distance_m": junction_distance, "commanded_segment": segment['kind'], "observed_velocity_mps": [actual.x, actual.y, actual.z]}

"""Saved-only original Native sign and bicycle roadway-use measurement."""
from __future__ import annotations

import hashlib
import json
import math

from native_site import canonical_sha, validate_site


def measure(site: dict, packet: dict, case: dict) -> dict:
    binding = validate_site(site)
    diagnostic = packet.get('source_kind') == 'diagnostic_fixture_capture'
    if packet.get("source_kind") not in ('original_native_capture', 'diagnostic_fixture_capture') or packet.get("site_sha256") != binding["site_sha256"]:
        raise ValueError("missing or mismatched original Native site source")
    body = {key: value for key, value in packet.items() if key != "seal_sha256"}
    if packet.get("seal_sha256") != canonical_sha(body):
        raise ValueError("original Native capture seal mismatch")
    if packet.get("case_id") != case.get("case_id") or packet.get("actor_blueprint_id") != site["bicycle_blueprint_id"]:
        raise ValueError("case or bicycle identity mismatch")
    if packet.get("map_name") != site["map_name"] or packet.get("street_id") != site["street_id"]:
        raise ValueError("map or street identity mismatch")
    frames = packet.get("frames")
    if not isinstance(frames, list) or len(frames) != 900:
        raise ValueError("45-second 20-Hz original frame history required")
    sign = site["sign"]
    roadway_frames = []
    trail_frames = []
    last_time = -math.inf
    for index, row in enumerate(frames):
        if row.get("original_frame") != index or row.get("actor_id") != packet.get("actor_id"):
            raise ValueError("original frame or actor continuity failure")
        t = row.get("elapsed_s")
        if not isinstance(t, (int, float)) or not math.isfinite(t) or t <= last_time or abs(t - index / 20) > 0.001:
            raise ValueError("original 20-Hz time continuity failure")
        last_time = t
        if row.get("sign_source_id") != sign["source_id"] or row.get("sign_posted_readback") is not True:
            raise ValueError("original sign readback missing")
        if row.get("segment") not in ("nonmotorized_trail", "governed_street_roadway"):
            raise ValueError("original route segment missing")
        if row.get("street_id") != site["street_id"]:
            raise ValueError("governed street readback mismatch")
        if row["segment"] == "governed_street_roadway":
            roadway_frames.append(index)
        else:
            trail_frames.append(index)
    if case.get("motion") == "enter_roadway" and (not trail_frames or not roadway_frames or min(roadway_frames) < min(trail_frames)):
        raise ValueError("roadway entry not observed after trail")
    if case.get("motion") in ("remain_trail", "stop_before_roadway") and roadway_frames:
        raise ValueError("roadway entry contradicts planned nonentry")
    return {"source_kind": "diagnostic_fixture_measurement" if diagnostic else "original_native_measurement", "case_id": case["case_id"], "site_sha256": binding["site_sha256"], "packet_sha256": hashlib.sha256(json.dumps(packet, sort_keys=True, separators=(",", ":")).encode()).hexdigest(), "frames": len(frames), "roadway_frames": len(roadway_frames), "trail_frames": len(trail_frames), "first_roadway_frame": min(roadway_frames) if roadway_frames else None, "sign_posted_original_frames": len(frames), "designation_source": site["engineer_designation_source"], "legal_assessment": "unresolved"}
